var RedactionActionDefinitions = map[RedactionAction]RedactionActionDefinition{
	RedactionActionRedact: {Name: RedactionActionRedact, Description: "Remove the unsafe value and retain only the safe replacement marker.", ValuePreserved: false, ReplacementUsed: true, ReplacementMarker: "[REDACTED]"},
	RedactionActionReject: {Name: RedactionActionReject, Description: "Reject the event, field, or bundle when unsafe content cannot be safely removed.", ValuePreserved: false, ReplacementUsed: false, ReplacementMarker: ""},
}

