func IsCanonicalLevel(value Level) bool {
	switch value {
	case LevelDebug, LevelInfo, LevelWarn, LevelError, LevelCritical:
		return true
	default:
		return false
	}
}

func IsKnownField(value FieldName) bool {
	_, ok := FieldDefinitions[value]
	return ok
}

func IsKnownEvent(value EventName) bool {
	_, ok := EventDefinitions[value]
	return ok
}

func ServiceDefinitionFor(value ServiceKey) (ServiceDefinition, bool) {
	definition, ok := ServiceDefinitions[value]
	return definition, ok
}

func IsRetentionTier(value RetentionTier) bool {
	switch value {
	case RetentionTierAuditGrade, RetentionTierDiagnosticReport, RetentionTierEphemeralDev, RetentionTierOperational:
		return true
	default:
		return false
	}
}

func FieldDefinitionFor(value FieldName) (FieldDefinition, bool) {
	definition, ok := FieldDefinitions[value]
	return definition, ok
}

func EventDefinitionFor(value EventName) (EventDefinition, bool) {
	definition, ok := EventDefinitions[value]
	return definition, ok
}

